'use strict';
let trainingDraft=null,trainingEditor='player',cycleKind='run';
const trainingLabels=()=>({player:L('Your team','Sua equipe'),enemy:L('Enemy team','Equipe inimiga')});
function trainingLoad(){if(trainingDraft)return;try{const c=JSON.parse(localStorage.getItem('grand-journey-training-v31'));if(!Training.validate(c,Progress.playerUnits().map(u=>u.id)))trainingDraft=c;}catch{}trainingDraft??=Training.defaults();}
function trainingStore(){try{localStorage.setItem('grand-journey-training-v31',JSON.stringify(trainingDraft));}catch{}}
function trainingPage(title,body){activeMetaScreen='training';show('<section class="training-config"><div class="top">'+metaButton('training-home','‹ '+L('Main menu','Menu principal'),'','mini')+'<span class="eyebrow">'+L('FREE TRAINING','TREINAMENTO GRATUITO')+'</span></div><h2>'+title+'</h2>'+body+'</section>');}
function trainingSourceOptions(side){const c=trainingDraft[side],d=G.DECKS.find(d=>d.id===c.source);return metaButton('training-choice-open',esc(d?d.name:L('Build a deck','Montar deck'))+' <span aria-hidden="true">›</span>','data-kind="source" data-side="'+side+'" aria-label="'+trainingLabels()[side]+' · '+L('Choose deck','Escolher deck')+'"','secondary training-choice');}
function trainingConfig(){trainingLoad();trainingStop();closeModal();trainingPage(L('Training','Treinamento'),'<p class="hint">'+L('Test strategies freely. Training gives no rewards and preserves your current run. Cards are shuffled and drawn normally.','Teste estratégias livremente. O treino não dá recompensas e preserva sua run atual. As cartas são embaralhadas e compradas normalmente.')+'</p><div class="training-settings"><div><span>'+L('Difficulty','Dificuldade')+'</span>'+metaButton('training-choice-open',({normal:L('Normal','Normal'),elite:'Elite',boss:'Boss'})[trainingDraft.difficulty]+' ›','data-kind="difficulty" aria-label="'+L('Choose difficulty','Escolher dificuldade')+'"','secondary training-choice')+'</div><div><span>'+L('Round wins to finish','Vitórias em rodadas para vencer')+'</span>'+metaButton('training-choice-open',trainingDraft.wins+' ›','data-kind="wins" aria-label="'+L('Choose round wins','Escolher número de vitórias')+'"','secondary training-choice')+'</div></div><p class="hint">'+L('Difficulty uses the normal, elite or boss opponent rules. Your chosen upgrades and relics are applied exactly.','A dificuldade usa as regras de oponente normal, elite ou boss. As melhorias e relíquias escolhidas são aplicadas como configuradas.')+'</p><div class="training-teams">'+['player','enemy'].map(key=>{const c=trainingDraft[key];return '<article class="training-team"><h3>'+trainingLabels()[key]+'</h3>'+trainingSourceOptions(key)+'<p>'+c.cards.length+'/20 · '+new Set(c.cards.map(v=>v.type)).size+' '+L('characters','personagens')+'</p>'+metaButton('training-edit',L('Cards & upgrades','Cartas e melhorias'),'data-side="'+key+'"')+metaButton('training-relics',L('Relics','Relíquias')+' · '+c.relics.length,'data-side="'+key+'"')+'</article>';}).join('')+'</div><p class="hint">'+L('20 cards per side, up to 4 copies per character. The normal energy, formation, reserve, refresh and fusion rules apply.','20 cartas por lado, até 4 cópias por personagem. Valem as regras normais de energia, formação, banco, reciclagem e fusão.')+'</p>'+metaButton('training-start',L('Start training','Iniciar treinamento'),'','primary'));}
function trainingEdit(side,keep=false){trainingEditor=side;const scroll=keep?$('screen-content')?.scrollTop||0:0,c=trainingDraft[side],counts={};c.cards.forEach(v=>counts[v.type]=(counts[v.type]||0)+1);trainingPage(trainingLabels()[side],'<div class="training-edit-tools"><b>'+c.cards.length+'/20</b>'+metaButton('training-choice-open',L('Upgrade all cards','Melhorar todas as cartas')+' ›','data-kind="level-all" data-side="'+side+'"','secondary training-batch')+metaButton('training-clear',L('Clear deck','Limpar deck'),'data-side="'+side+'"','mini')+'</div><p class="hint">'+L('Choose copies and upgrade levels. Training uses all currently revealed characters, without consuming collection copies.','Escolha as cópias e os níveis de melhoria. O treino usa os personagens já revelados, sem consumir cópias da coleção.')+'</p><div class="meta-card-grid training-card-grid">'+Progress.playerUnits().map(u=>{const n=counts[u.id]||0,level=c.cards.find(v=>v.type===u.id)?.level||0;return '<article>'+cardFace({uid:u.id,type:u.id,level},'training-info','data-side="'+side+'"',{artifacts:[]})+'<div class="copy-controls">'+metaButton('training-minus','−','data-id="'+u.id+'" data-side="'+side+'" aria-label="'+L('Remove copy of ','Remover cópia de ')+esc(u.name)+'" '+(!n?'disabled':''),'mini')+'<b>'+n+'/4</b>'+metaButton('training-plus','+','data-id="'+u.id+'" data-side="'+side+'" aria-label="'+L('Add copy of ','Adicionar cópia de ')+esc(u.name)+'" '+(n>=4||c.cards.length>=20?'disabled':''),'mini')+'</div>'+metaButton('training-choice-open','Upgrade '+level+' ›','data-kind="level" data-side="'+side+'" data-id="'+u.id+'" aria-label="'+esc(u.name)+' · Upgrade '+level+'" '+(!n?'disabled':''),'secondary training-level-button')+'</article>';}).join('')+'</div><div class="training-sticky">'+metaButton('training-config',L('Done · back to settings','Concluir · voltar às configurações'),'','primary')+'</div>');if(keep)$('screen-content').scrollTop=scroll;}
let trainingChoiceContext=null;
function trainingPicker(kind,side='player',id=''){
 const c=trainingDraft[side],names={source:trainingLabels()[side]+' · '+L('Choose deck','Escolher deck'),difficulty:L('Difficulty','Dificuldade'),wins:L('Round wins to finish','Vitórias em rodadas para vencer'),'level-all':L('Upgrade all cards','Melhorar todas as cartas'),level:(G.BY[id]?.name||'')+' · Upgrade'};
 if(!Object.hasOwn(names,kind))return;trainingChoiceContext={kind,side,id};
 let options=[],chosen='';
 if(kind==='source'){chosen=c.source;options=G.DECKS.filter(d=>Progress.profile.decks.includes(d.id)||d.id===c.source).map(d=>({value:d.id,label:d.name,deck:d}));options.push({value:'custom',label:L('Build a deck','Montar deck')});}
 if(kind==='difficulty'){chosen=trainingDraft.difficulty;options=[{value:'normal',label:L('Normal','Normal')},{value:'elite',label:'Elite'},{value:'boss',label:'Boss'}];}
 if(kind==='wins'){chosen=String(trainingDraft.wins);options=Array.from({length:10},(_,i)=>({value:String(i+1),label:String(i+1)+' '+L(i?'round wins':'round win',i?'vitórias em rodadas':'vitória em rodada')}));}
 if(kind==='level'||kind==='level-all'){chosen=kind==='level'?String(c.cards.find(v=>v.type===id)?.level||0):'';options=[0,1,2].map(n=>({value:String(n),label:n===0?L('No upgrade','Sem melhoria'):'Upgrade '+n}));}
 openModal('<h2>'+esc(names[kind])+'</h2><div class="stack training-options '+(kind==='wins'?'training-number-options':'')+'">'+options.map(o=>'<button class="secondary training-option '+(chosen===o.value?'chosen':'')+'" data-act="training-choice-pick" data-value="'+o.value+'" aria-pressed="'+(chosen===o.value)+'">'+(o.deck?'<span class="training-deck-faces">'+o.deck.faces.slice(0,3).map(type=>'<img src="'+CA[type].portrait+'" alt="">').join('')+'</span>':'')+'<span>'+esc(o.label)+'</span><b aria-hidden="true">'+(chosen===o.value?'✓':'›')+'</b></button>').join('')+'</div>');$('overlay').querySelector('.modal').classList.add('training-picker');
}
function trainingPick(value){if(!trainingChoiceContext)return;const {kind,side,id}=trainingChoiceContext,c=trainingDraft[side];let editor=false;
 if(kind==='source'){if(value==='custom'){c.source='custom';editor=true;}else if(G.DECKS.some(d=>d.id===value&&(Progress.profile.decks.includes(d.id)||d.id===c.source)))trainingDraft[side]=Training.side(value);else return;}
 else if(kind==='difficulty'){if(!['normal','elite','boss'].includes(value))return;trainingDraft.difficulty=value;}
 else if(kind==='wins'){const n=Number(value);if(!Number.isInteger(n)||n<1||n>10)return;trainingDraft.wins=n;}
 else if(kind==='level'||kind==='level-all'){const n=Number(value);if(![0,1,2].includes(n))return;c.cards.filter(v=>kind==='level-all'||v.type===id).forEach(v=>v.level=n);c.source='custom';editor=true;}
 trainingStore();closeModal();trainingChoiceContext=null;if(editor)trainingEdit(side,true);else trainingConfig();
}
function trainingRelics(side){trainingEditor=side;const ids=trainingDraft[side].relics;trainingPage(trainingLabels()[side]+' · '+L('Relics','Relíquias'),'<p class="hint">'+L('Choose equipped relics within a 4 × 4 bag. No relics is also valid.','Escolha as relíquias equipadas dentro de uma bolsa 4 × 4. Também é possível jogar sem relíquias.')+'</p><b>'+ids.reduce((n,id)=>n+G.relicShape(id).length,0)+'/16</b><div class="training-relic-list">'+G.ARTIFACTS.map(a=>'<button class="offer '+(ids.includes(a.id)?'chosen':'')+'" data-act="training-toggle-relic" data-id="'+a.id+'" data-side="'+side+'" aria-pressed="'+ids.includes(a.id)+'">'+relicIcon(a.id)+'<span><b>'+esc(relicTitle(a))+'</b>'+relicStamp(a.id)+'<small>'+esc(relicDescription(a))+'</small></span><strong>'+(ids.includes(a.id)?'✓':'+')+'</strong></button>').join('')+'</div><div class="training-sticky">'+metaButton('training-config',L('Done · back to settings','Concluir · voltar às configurações'),'','primary')+'</div>');}
function trainingStop(){cancelAnimationFrame(raf);if(S?.training){battle=null;selected=null;S=trainingReturnRun;trainingReturnRun=null;modalResume=false;save();}}
function trainingStart(){trainingLoad();const error=Training.validate(trainingDraft,Progress.playerUnits().map(u=>u.id));if(error){toast(error==='relics'?L('These relics do not fit in the bag.','Estas relíquias não cabem na bolsa.'):L('Each deck needs 20 cards, with at most 4 copies per character.','Cada deck precisa de 20 cartas, com no máximo 4 cópias por personagem.'));return;}trainingStop();closeModal();trainingStore();trainingReturnRun=S;S=Training.build(trainingDraft,Date.now()>>>0,Progress.playerUnits().map(u=>u.id));S.current.name=L('Training','Treinamento');battle=null;selected=null;render();}
function trainingHome(){trainingStop();closeModal();home();}
const trainingHomeButtons=metaHomeButtons;metaHomeButtons=function(){return metaButton('training-config',L('Training','Treinamento'))+trainingHomeButtons();};
const trainingFusionTip=tutorialFusionTip;tutorialFusionTip=function(){if(!S?.training)trainingFusionTip();};
const trainingResultBase=resultView;resultView=function(){if(!S?.training)return trainingResultBase();const round=S.phase==='roundResult';show('<section class="training-result"><div class="eyebrow">'+L('TRAINING · NO REWARDS','TREINAMENTO · SEM RECOMPENSAS')+'</div><h2>'+L(round?'Round complete':S.phase==='victory'?'Victory':'Defeat',round?'Rodada encerrada':S.phase==='victory'?'Vitória':'Derrota')+'</h2><div class="bigscore">'+S.score[0]+' : '+S.score[1]+'</div><p>'+L('First to ','Primeiro a ')+G.winsNeeded(S)+' '+L('round wins','vitórias em rodadas')+'</p><div class="stack">'+(round?metaButton('next-round',L('Prepare round ','Preparar rodada ')+(S.round+1),'','primary'):metaButton('training-start',L('Repeat · same settings','Repetir · mesmas configurações'),'','primary'))+metaButton('training-config',L('Change settings','Alterar configurações'))+metaButton('training-home',L('Main menu','Menu principal'))+'</div>'+damageReport(false)+'</section>');};
function trainingPause(){openModal('<h2>'+L('Training','Treinamento')+'</h2><div class="stack">'+metaButton('close',L('Return to combat','Voltar ao combate'))+metaButton('training-config',L('Change settings','Alterar configurações'))+metaButton('training-home',L('Main menu','Menu principal'))+'</div>');}
window.JourneyTraining={guard(e){if(e.type!=='click')return false;const el=e.target.closest?.('[data-act]'),a=el?.dataset.act;if(!a||el.disabled)return false;
 if(a==='cycle-pile'||a==='cycle-summary'||a==='cycle-info'||a==='detail-back'&&detailNav?.mode==='cycle'||a==='close'&&detailNav?.mode==='cycle'&&document.querySelector('#overlay .character-modal')&&!$('overlay-parent')){e.preventDefault();e.stopImmediatePropagation();if(a==='cycle-pile')cyclePile(el.dataset.kind);else if(a==='cycle-summary')tutorialPiles();else if(a==='cycle-info'){const cards=cycleSorted();detailNav={mode:'cycle',cards,index:+el.dataset.index};navigateDetail(0);}else cyclePile(cycleKind);return true;}
 const special=a.startsWith('training-'),inTraining=!!S?.training;if(!special&&!(inTraining&&(['home','new','menu','abandon-confirm','abandon-run'].includes(a)||a.startsWith('hack'))))return false;
 e.preventDefault();e.stopImmediatePropagation();AudioSystem.unlock();
 if(inTraining&&a==='menu'){trainingPause();return true;}if(inTraining&&a.startsWith('hack')){toast(L('Training does not change permanent resources.','O treino não altera recursos permanentes.'));return true;}if(inTraining&&['home','new','abandon-confirm','abandon-run'].includes(a)){trainingHome();return true;}
 if(a==='training-choice-open'){trainingPicker(el.dataset.kind,el.dataset.side,el.dataset.id);}
 else if(a==='training-choice-pick'){trainingPick(el.dataset.value);}
 else if(a==='training-config'){if(battle&&!battle.result&&!inTraining){toast(L('Finish the current battle first.','Termine o combate atual primeiro.'));return true;}trainingConfig();}
 else if(a==='training-home')trainingHome();else if(a==='training-start')trainingStart();else if(a==='training-edit')trainingEdit(el.dataset.side);else if(a==='training-relics')trainingRelics(el.dataset.side);
 else if(a==='training-info'){trainingEditor=el.dataset.side;const c=trainingDraft[trainingEditor].cards.find(v=>v.type===el.dataset.id)||{type:el.dataset.id,level:0};detailNav={mode:'training-preview',cards:[c],index:0};detailFusionPreview=false;detail(c,false,true);}
 else if(a==='training-plus'||a==='training-minus'||a==='training-clear'){const c=trainingDraft[el.dataset.side],id=el.dataset.id,n=c.cards.filter(v=>v.type===id).length;if(a==='training-clear')c.cards=[];else if(a==='training-plus'&&n<4&&c.cards.length<20)c.cards.push({type:id,level:c.cards.find(v=>v.type===id)?.level||0});else if(a==='training-minus'){const i=c.cards.findIndex(v=>v.type===id);if(i>=0)c.cards.splice(i,1);}c.source='custom';trainingStore();trainingEdit(el.dataset.side,true);}
 else if(a==='training-toggle-relic'){const c=trainingDraft[el.dataset.side],next=c.relics.includes(el.dataset.id)?c.relics.filter(id=>id!==el.dataset.id):[...c.relics,el.dataset.id];if(G.packBag(next)){c.relics=next;trainingStore();trainingRelics(el.dataset.side);}else toast(L('These relics do not fit in a 4 × 4 bag.','Estas relíquias não cabem em uma bolsa 4 × 4.'));}return true;
}};
const cycleLabels=()=>({run:S?.training?L('Training deck','Deck do treino'):L('Run deck','Deck da run'),draw:L('Draw pile','Pilha de compra'),discard:L('Discard pile','Pilha de descarte'),hand:L('Hand','Mão'),bound:L('Bound cards','Cartas vinculadas'),exiled:L('Set aside','Afastadas')});
function cycleSorted(){return CycleData.cards(S,cycleKind).sort((a,b)=>G.BY[a.type].name.localeCompare(G.BY[b.type].name)||a.level-b.level||a.uid.localeCompare(b.uid));}
function cyclePile(kind){if(!S||!Object.hasOwn(cycleLabels(),kind))return;cycleKind=kind;detailNav=null;const cards=cycleSorted();openModal('<h2>'+cycleLabels()[kind]+' · '+cards.length+'</h2><div class="cycle-cards">'+(cards.length?cards.map((c,i)=>'<article>'+cardFace(c,'cycle-info','data-index="'+i+'"')+(kind==='bound'?'<small>'+cycleBoundLabel(c.uid)+'</small>':'')+'</article>').join(''):'<p class="empty-state">'+L('No cards in this pile.','Nenhuma carta nesta pilha.')+'</p>')+'</div>'+metaButton('cycle-summary','‹ '+L('Card cycle','Ciclo das cartas')));}
function cycleBoundLabel(uid){for(const [slots,label]of[[S.board,L('Field','Campo')],[S.bench,L('Reserve','Banco')]])for(let i=0;i<slots.length;i++){const leader=slots[i];if(leader&&(leader===uid||S.fusions?.[leader]?.includes(uid)))return label+' '+(i+1)+(S.fusions?.[leader]?' · '+L('Fusion member','Cópia da fusão'):'');}return '';}
tutorialPiles=function(){if(!S)return;detailNav=null;const labels=cycleLabels();openModal('<h2>'+L('Card cycle','Ciclo das cartas')+'</h2><div class="run-summary cycle-summary">'+Object.keys(labels).map(kind=>'<button data-act="cycle-pile" data-kind="'+kind+'"><b>'+CycleData.ids(S,kind).length+'</b><span>'+labels[kind]+'</span></button>').join('')+'</div><p>'+L('Tap a pile to see its cards. Bound cards include field, reserve and all fusion copies. When draw runs out, discard is shuffled. Freeze during setup keeps your remaining hand for the next round.','Toque em uma pilha para ver suas cartas. Cartas vinculadas incluem campo, banco e todas as cópias das fusões. Quando a compra acaba, o descarte é embaralhado. Congelar no preparo mantém a mão restante para a próxima rodada.')+'</p>');};
